1	const IN_PROGRESS_STATUSES = new Set([
2	  "STATUS_IN_PROGRESS",
3	  "STATUS_HALFTIME",
4	  "STATUS_END_PERIOD",
5	]);
6	
7	const SCHEDULED_STATUS = "STATUS_SCHEDULED";
8	const FINAL_STATUS = "STATUS_FINAL";
9	const MAX_RECENTLY_STARTED_GAME_AGE_MS = 6 * 60 * 60 * 1000;
10	
11	export function isScheduledGame(status?: string): boolean {
12	  return status === SCHEDULED_STATUS;
13	}
14	
15	export function isFinalGame(status?: string): boolean {
16	  return status === FINAL_STATUS;
17	}
18	
19	export function isInProgressGame(status?: string): boolean {
20	  return !!status && IN_PROGRESS_STATUSES.has(status);
21	}
22	
23	export function shouldShowGameScore(status?: string): boolean {
24	  return !isScheduledGame(status);
25	}
26	
27	export function shouldPollGameStats(status?: string): boolean {
28	  return !isScheduledGame(status) && !isFinalGame(status);
29	}
30	
31	export function shouldShowScheduledOrFinalDate(status?: string): boolean {
32	  return isScheduledGame(status) || isFinalGame(status);
33	}
34	
35	export function shouldShowLiveGameDetails(status?: string): boolean {
36	  return !isScheduledGame(status) && !isFinalGame(status);
37	}
38	
39	export function shouldShowGameChannel(status?: string): boolean {
40	  return !isFinalGame(status);
41	}
