43	function isRecentlyStartedGame(isoDate?: string): boolean {
44	  if (!isoDate) {
45	    return false;
46	  }
47	  const startTime = new Date(isoDate).getTime();
48	  if (Number.isNaN(startTime)) {
49	    return false;
50	  }
51	  const now = Date.now();
52	  return (
53	    now >= startTime && now - startTime <= MAX_RECENTLY_STARTED_GAME_AGE_MS
54	  );
55	}
56	
57	export function isLiveDashboardGame(game: Game): boolean {
58	  if (isFinalGame(game.gameStatus) || !!game.winner || game.final === true) {
59	    return false;
60	  }
61	
62	  if (isInProgressGame(game.gameStatus)) {
63	    return true;
64	  }
65	
66	  if (isScheduledGame(game.gameStatus)) {
67	    return isRecentlyStartedGame(game.isoDate);
68	  }
69	
70	  return true;
71	}
