3	export const fetcher = async (url: string) => {
4	  const response = await fetch(url);
5	  const payload = await response.json().catch(() => null);
6	
7	  if (!response.ok) {
8	    const apiError = payload as ApiError | null;
9	    const errorMessage =
10	      apiError?.message || `Request failed with status ${response.status}`;
11	    const error = new Error(errorMessage) as Error & {
12	      status?: number;
13	      code?: string;
14	      details?: string;
15	    };
16	    error.status = response.status;
17	    error.code = apiError?.code;
18	    error.details = apiError?.details;
19	    throw error;
20	  }
21	
22	  return payload;
23	};
