6	  const league = parseLeagueId(searchParams.get("league"));
7	  if (!league) {
8	    return new Response("Bad request: Invalid league", { status: 400 });
9	  }
10	  const week = searchParams.get("week");
11	  const seasonType = searchParams.get("seasonType");
12	  const year = searchParams.get("year");
13	  const date = searchParams.get("date");
14	  const timezone = searchParams.get("timezone");
15	
16	  const games = await fetch(
17	    `${process.env.BACKEND_URL}/api/v1/games?league=${league}${year ? `&year=${year}` : ""}${seasonType ? `&seasonType=${seasonType}` : ""}${week ? `&week=${week}` : ""}${date ? `&date=${date}` : ""}${timezone ? `&userTimeZone=${encodeURIComponent(timezone)}` : ""}`,
18	    {
19	      headers: {
20	        "x-api-key": process.env.API_KEY || "",
21	      },
22	    },
23	  );
24	
25	  const rawBody = await games.text();
26	  if (!games.ok) {
27	    return new Response(rawBody || "Backend request failed", {
28	      status: games.status,
29	      headers: {
30	        "content-type": games.headers.get("content-type") || "text/plain",
31	      },
32	    });
33	  }
34	
35	  const body = rawBody ? JSON.parse(rawBody) : {};
36	  return NextResponse.json(body.content ?? []);
